#!/bin/bash
# list.sh and remind.sh check DATE: a malformed date exits 2 with the message; a valid date works as before.
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
export BOOKINGS=$t

bash src/list.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(bash src/list.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "bad date message"; fail=1; }
bash src/list.sh 2026-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "month 13 should exit 2"; fail=1; }
bash src/list.sh 2026-01-32 >/dev/null 2>&1; [ $? = 2 ] || { echo "day 32 should exit 2"; fail=1; }
[ "$(bash src/list.sh 2026-01-01)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "a valid date should list its bookings"; fail=1; }
[ "$(bash src/list.sh 2026-02-01)" = '' ] || { echo "a valid date with no bookings should print nothing"; fail=1; }

bash src/remind.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "remind: a malformed date should exit 2"; fail=1; }
[ "$(bash src/remind.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "remind: bad date message"; fail=1; }
[ "$(bash src/remind.sh 2026-01-01)" = 'reminder to y: kaede 2026-01-01 09:00-10:00' ] || { echo "remind: a valid date should remind"; fail=1; }

rm -f "$t"; exit $fail

